import {yanziAssets} from './yanzi-assets.js';
import {traditional} from './chinese-traditional.js';
import {registerTranslations} from './localization.js';
export const yanziTitle='Yan Zi · A Conversational Digital Human';
export const yanziSummary='A locally deployed conversational character connects speech recognition, a knowledge-based agent and Unity HDRP through voice, lip movement and animation.';
registerTranslations([[yanziTitle,'晏子 · 可对话数字人'],[yanziSummary,'通过本地语音识别、知识库智能体与 Unity HDRP，将语音、口型和动画连接为可对话的数字人展项。'],['CASE 04 / CONVERSATIONAL DIGITAL HUMAN','案例 04 / 可对话数字人']]);
const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createYanziDetails(){
 let dialog=null,opener=null;
 const t=(zh,en)=>document.documentElement.lang==='en'?en:document.documentElement.lang==='zh-Hant'?[...zh].map(c=>traditional[c]||c).join(''):zh;
 function dismissAsset(){const viewer=dialog?.querySelector('.ex-asset-viewer');const key=viewer?.dataset.returnKey;viewer?.remove();if(key)dialog?.querySelector(`[data-yz-asset="${key}"]`)?.focus({preventScroll:true});}
 function showAsset(id){dismissAsset();const a=yanziAssets[id],button=dialog.querySelector(`[data-yz-asset="${id}"]`),label=button.querySelector('img').alt;
  const viewer=document.createElement('div');viewer.className='ex-asset-viewer';viewer.dataset.returnKey=id;viewer.setAttribute('role','dialog');viewer.setAttribute('aria-label',label);viewer.tabIndex=-1;
  viewer.innerHTML=`<div class="ex-asset-bar"><span>${esc(label)}</span><button type="button" data-yz-fit>${t('原尺寸查看','View at full size')}</button><button type="button" data-yz-dismiss>${t('返回详情 ×','Back to details ×')}</button></div><div class="ex-asset-stage"><img src="${a.full}" alt="${esc(label)}"></div>`;
  viewer.querySelector('[data-yz-dismiss]').onclick=dismissAsset;viewer.querySelector('[data-yz-fit]').onclick=e=>{const large=viewer.classList.toggle('is-zoomed');e.target.textContent=t(large?'适应窗口':'原尺寸查看',large?'Fit to window':'View at full size');};dialog.append(viewer);viewer.focus();
 }
 function close(){if(!dialog)return;dialog.close();dialog.remove();dialog=null;if(opener?.isConnected)opener.focus({preventScroll:true});}
 function render(){if(!dialog)return;
  const scroll=dialog.querySelector('.ex-reader-body')?.scrollTop||0;
  dialog.setAttribute('aria-label',t('展项详情 · 数字人晏子','Exhibit details · Digital Yan Zi'));
  dialog.innerHTML=`<header class="ex-window-bar"><span>${t('风从东方来 / 展项详情','WIND FROM THE EAST / EXHIBIT DETAILS')}</span><button class="ex-close" type="button">${t('关闭 ×','Close ×')}</button></header>
  <div class="ex-reader-body yz-body">${yzMarkup(t)}</div><footer class="ex-reader-footer"><button type="button" data-yz-back>${t('← 返回展项列表','← Back to exhibit details')}</button><span>04 / THE METAHUMAN YANZI</span></footer>`;
  dialog.querySelector('.ex-close').onclick=close;dialog.querySelector('[data-yz-back]').onclick=close;
  dialog.querySelectorAll('[data-yz-asset]').forEach(b=>b.onclick=()=>showAsset(b.dataset.yzAsset));dialog.querySelectorAll('[data-yz-jump]').forEach(b=>b.onclick=()=>dialog.querySelector('#'+b.dataset.yzJump).scrollIntoView({behavior:'instant',block:'start'}));dialog.querySelector('.ex-reader-body').scrollTop=scroll;
 }
 function open(trigger){opener=trigger;if(!dialog){dialog=document.createElement('dialog');dialog.className='ex-reader ex-yz-reader';dialog.setAttribute('data-no-localize','');dialog.addEventListener('cancel',e=>{e.preventDefault();if(dialog.querySelector('.ex-asset-viewer'))dismissAsset();else close();});document.body.append(dialog);render();dialog.showModal();}else{render();dialog.querySelector('.ex-reader-body').scrollTop=0;}}
 document.addEventListener('portfolio-preferences',render);
 return {open,close,destroy(){close();document.removeEventListener('portfolio-preferences',render);}};
}


function yzMarkup(t){
 const para=(zh,en)=>`<p>${t(zh,en)}</p>`;
 const photo=(id,zh,en,kind='')=>{const a=yanziAssets[id],label=t(zh,en);return `<figure class="yz-image ${kind}"><button type="button" data-yz-asset="${id}" aria-label="${esc(t('放大：','Enlarge: ')+label)}"><img src="${a.src}" alt="${esc(label)}" width="${a.width}" height="${a.height}" loading="lazy" decoding="async"></button><figcaption>${label}<span aria-hidden="true"> ↗</span></figcaption></figure>`;};
 const head=(id,zh,en,tag)=>`<header class="yz-heading"><span>${id} / ${tag}</span><h2>${t(zh,en)}</h2></header>`;
 const note=(zh,en)=>`<p class="yz-note">${t(zh,en)}</p>`;
return `<article class="yz-page">
  <header class="ex-hi-masthead"><span>QI CULTURE CLASSICS CENTER</span><span>CASE 04 / THE METAHUMAN YANZI</span></header>
  <section class="yz-hero"><div><span class="yz-kicker">VOICE → KNOWLEDGE → PRESENCE</span><h1>${t('让历史人物\n进入一次对话','A HISTORICAL FIGURE.\nA LIVE CONVERSATION.')}</h1><h2>${t('晏子 · 可对话数字人',yanziTitle)}</h2>${para('展项以“与晏子对话”为体验入口，让历史人物从典籍叙述走向面对面的交流。观众通过语音提问，数字人以声音、字幕、口型和身体动作回应。本地大模型与知识库提供对话内容，Unity HDRP 将这些内容转化为具有角色形象与空间存在感的展厅体验。','The exhibit invites visitors into a conversation with Yan Zi, bringing a historical figure from the written page into a face-to-face encounter. Spoken questions receive replies through voice, captions, mouth movement and gesture. A local language model and knowledge base supply the dialogue, while Unity HDRP gives it a character and a presence in the gallery.')}
  <dl class="yz-specs"><div><dt>${t('集成平台','INTEGRATION')}</dt><dd>Unity HDRP</dd></div><div><dt>${t('现场配置','SITE HARDWARE')}</dt><dd>Core i7 / RTX 5070 Ti</dd></div><div><dt>${t('现场模型','SITE MODEL')}</dt><dd>Qwen2.5 / Ollama</dd></div></dl></div>${photo('site-06','现场：观众与晏子对话','On site: visitors encounter Yan Zi','yz-hero-photo')}</section>
  <nav class="yz-index" aria-label="${t('技术章节','Technical sections')}">${[['01','系统全貌','System'],['02','语音输入','Input'],['03','本地智能体','Agent'],['04','形象与渲染','Character'],['05','声音与表现','Output'],['06','集成细节','Integration'],['07','现场记录','On site']].map(([id,zh,en])=>`<button type="button" data-yz-jump="yz-${id}">${id} / ${t(zh,en)}</button>`).join('')}</nav>
  <section class="yz-block" id="yz-01">${head('01','从一句提问，到一个会回应的角色','From a spoken question to an embodied reply','SYSTEM ARCHITECTURE')}
  ${para('这套系统分为输入、语义处理和角色表现三个部分。FunASR 将声音转成文字；Coze 组织人物设定与知识，并连接 Ollama 中的大模型；回答经 TTS 转为声音，再由 Unity 协调播放、口型与动画。','The system separates input, language processing and character presentation. FunASR converts speech into text. Coze coordinates the persona and knowledge with a model served through Ollama. TTS turns the answer into speech; Unity coordinates playback, lip movement and animation.')}
  <ol class="yz-pipeline">${[['唤醒 / 录音','Wake / capture','Windows Speech · microphone'],['流式识别','Speech to text','FunASR · WebSocket'],['角色与知识','Persona / knowledge','Coze Studio · Docker'],['本地推理','Local inference','Ollama · Qwen2.5'],['语音合成','Text to speech','TTS'],['角色输出','Character output','Unity · HDRP']].map(([zh,en,small],i)=>`<li><span>0${i+1}</span><strong>${t(zh,en)}</strong><small>${small}</small></li>`).join('')}</ol>
  <div class="yz-split"><div><h3>${t('文字通道与声音通道','Two connected output channels')}</h3>${para('回答文字进入字幕显示；合成音频进入 AudioSource。口型跟随音频变化，身体在 idle 与讲话动画之间切换。把这几种输出区分开，才能分别调试“听清、答对、说出、演出”四个环节。','Answer text feeds the caption display; synthesized audio feeds AudioSource. Mouth movement follows the audio while the body switches between idle and speaking animation. Separating these outputs makes recognition, answering, speech and performance individually testable.')}</div><div class="yz-callout"><span>DESIGN INTENT</span>${para('设计的重点是把语音、知识与人物表现连接起来：以提问引入文化内容，再通过可见、可听的角色回应，让观众以对话的方式接近晏子的故事与思想。','The design connects voice, knowledge and character performance. A visitor’s question opens a cultural topic; a visible and audible reply offers a conversational way into Yan Zi’s stories and ideas.')}</div></div></section>
  <section class="yz-block" id="yz-02">${head('02','把现场声音变成可提交的问题','Turning speech into a question','WAKE / RECORD / TRANSCRIBE')}
  <div class="yz-three"><div><h3>01 / ${t('唤醒事件','Wake event')}</h3>${para('WatchwordWindows 使用 Windows Speech 的 KeywordRecognizer，将关键词识别连接到 UnityEvent。唤醒事件启动交互，随后由语音识别接收完整问题，形成从靠近展项到开口交流的操作顺序。','WatchwordWindows connects Windows Speech KeywordRecognizer to UnityEvent. A wake event initiates the interaction, followed by speech recognition for the complete question, forming a sequence from approaching the exhibit to beginning a conversation.')}</div><div><h3>02 / ${t('音频采集','Audio capture')}</h3>${para('OnlineAudio 以 16,000 Hz 采集声音，通过 10 秒循环录音缓冲和 ConcurrentQueue&lt;byte[]&gt; 队列组织音频数据。开始录音前清空旧队列，再调用 Microphone.Start，为后续流式识别准备连续的声音输入。','OnlineAudio captures speech at 16,000 Hz, organizing audio through a ten-second looping buffer and a ConcurrentQueue&lt;byte[]&gt;. It clears the previous queue before calling Microphone.Start, preparing continuous input for streaming recognition.')}</div><div><h3>03 / ${t('连接识别服务','ASR connection')}</h3>${para('AudioRecorder 通过 WebSocket 连接本地 STT 服务，注册 OnMessage、OnOpen 和 OnError。收到识别结果后可显示问题文本，并在待机提示与聆听提示之间切换。','AudioRecorder connects to the local STT service through WebSocket, registering OnMessage, OnOpen and OnError. The visible UI methods display the recognized question and switch between idle and listening prompts.')}</div></div>
  <div class="yz-grid">${photo('wake','WatchwordWindows：关键词与事件回调','WatchwordWindows: keywords and event callbacks')}${photo('online-audio','OnlineAudio：采样率、循环缓冲与队列','OnlineAudio: sample rate, looping buffer and queue')}${photo('recorder','AudioRecorder：WebSocket 生命周期与提示状态','AudioRecorder: WebSocket lifecycle and prompt states')}${photo('funasr','FunASR：所选语音识别项目的资料截图','FunASR: reference screenshot of the selected ASR project')}</div></section>
  <section class="yz-block" id="yz-03">${head('03','让回答围绕“晏子”展开','Giving the answer a persona and context','COZE / KNOWLEDGE / OLLAMA')}
  <div class="yz-split"><div><h3>${t('智能体负责角色和内容组织','The agent organizes persona and content')}</h3>${para('Coze 智能体通过身份、性格、人物经历与语言风格设定，建立晏子的对话角色，并以第一人称组织回答。本地知识库为对话提供文化内容，使角色设定与展览主题在同一套问答流程中衔接。','The Coze agent establishes Yan Zi’s conversational persona through identity, personality, biography and speaking style, with responses framed in the first person. A local knowledge base supplies cultural context, connecting the character to the exhibition’s themes within the dialogue workflow.')}</div><div><h3>${t('Unity 接口负责发送问题','The Unity adapter submits the question')}</h3>${para('Coze.cs 继承 LLM，提供本地 / 云端地址选择、Bot ID、用户标识和 Token 配置，并拼接 /v3/chat 地址。截图中的本地默认地址为 127.0.0.1:8888；PostMsg 将人物提示、语言信息和用户问题组织后，启动请求协程。','Coze.cs extends LLM and exposes local/cloud address selection, Bot ID, user identity and token settings. It builds the /v3/chat endpoint; the shown local default is 127.0.0.1:8888. PostMsg assembles persona, language and question context before starting a request coroutine.')}</div></div>
  <div class="yz-grid">${photo('coze-agent','Coze：人物设定与对话测试','Coze: persona configuration and dialogue trial')}${photo('coze-code','Coze.cs：本地接口适配','Coze.cs: local API adapter')}${photo('docker','Docker：本地 Coze 服务容器','Docker: local Coze service containers')}${photo('ollama','Ollama：本地运行环境记录','Ollama: local runtime record')}</div>
  <div class="yz-callout"><h3>${t('本地模型部署','Local model deployment')}</h3>${para('现场采用 Qwen2.5，通过 Ollama 在 Core i7 + RTX 5070 Ti 设备上本地运行，并由 Coze 智能体调用。Coze 配置中的模型标签为 qwen2.5:0.5b；Docker 承载本地智能体服务，Unity 则作为观众交互与角色呈现的前端，将模型回答接入展项体验。','The installation uses Qwen2.5, served locally through Ollama on a Core i7 + RTX 5070 Ti machine and accessed by the Coze agent. The Coze configuration is labelled qwen2.5:0.5b. Docker hosts the local agent service, while Unity connects model responses to visitor interaction and character presentation.')}</div>${photo('coze-home','Coze Studio：本地智能体工作区','Coze Studio: local agent workspace','yz-small-evidence')}</section>
  <section class="yz-block" id="yz-04">${head('04','从人物定制到实时渲染','From character design to real-time rendering','METAHUMAN / UNITY HDRP')}
  ${para('角色形象通过 MetaHuman 定制，并在 Unity HDRP 中完成场景集成。人物外观、材质、灯光与动画共同构成晏子的视觉表现，让对话内容拥有可辨认的人物形象，也为观众提供面对面交流的视觉焦点。','The character is customized with MetaHuman and integrated into a Unity HDRP scene. Appearance, materials, lighting and animation work together to give Yan Zi a recognizable identity and a visual focus for face-to-face conversation.')}
  <div class="yz-grid">${photo('unity','Unity：角色与展项场景集成','Unity: character and exhibit scene integration')}${photo('unity-first','初版 Unity：角色与 Animator 状态图','Initial Unity version: character and Animator graph')}</div>
  <div class="yz-split"><div><h3>${t('皮肤：贴图和光照响应','Skin: texture and light response')}</h3>${para('面部材质采用 HDRP/Lit，以 Base Map、Mask Map 和 Normal Map 组织表面色彩与细节。颜色贴图建立肤色，法线贴图丰富局部光照变化，再结合场景灯光调整人物在屏幕中的面部层次。','The face uses HDRP/Lit, with Base Map, Mask Map and Normal Map organizing surface color and detail. Color textures establish skin tone, while normal maps add local lighting variation. Scene lighting shapes the depth and definition of the face on screen.')}</div><div><h3>${t('毛发：轮廓与材质调试','Hair: silhouette and material tuning')}</h3>${para('毛发细节强化人物的发型与头部轮廓。通过 HDRP/Lit 的双面显示、平滑度等参数调整发丝的光照响应，使毛发与面部、服饰共同形成完整的角色外观。','Hair detail defines the hairstyle and head silhouette. Double-sided rendering and smoothness settings in HDRP/Lit shape its response to light, bringing the hair, face and costume together as one character.')}</div></div>
  <div class="yz-materials">${photo('face-textures','面部贴图资源','Face texture assets')}${photo('face-material','面部材质参数','Face material settings')}${photo('hair-detail','毛发细节与人物轮廓','Hair detail and character silhouette')}${photo('hair-material','毛发材质参数','Hair material settings')}</div></section>
  <section class="yz-block" id="yz-05">${head('05','让声音、嘴部和身体形成同一回应','Coordinating voice, mouth and body','TTS / BLENDSHAPE / ANIMATOR')}
  <div class="yz-output"><div><span>TEXT</span><strong>${t('回答文字','Answer text')}</strong></div><b>→</b><div><span>TTS</span><strong>${t('生成语音','Synthesize speech')}</strong></div><b>→</b><div><span>AUDIO SOURCE</span><strong>${t('播放与音量','Playback / amplitude')}</strong></div><b>→</b><div><span>TALK / IDLE</span><strong>${t('口型与动画','Mouth / animation')}</strong></div></div>
  <div class="yz-split"><div><h3>${t('音量驱动的口型','Amplitude-driven lip movement')}</h3>${para('AudioMouthControllerAdvanced 将 AudioSource 与 SkinnedMeshRenderer 连接起来，通过 talkBlendShapeIndex 控制嘴部开合。播放时读取音频振幅，乘以放大系数，再用 SmoothDamp 平滑权重变化。默认放大系数为 100，平滑时间为 0.1 秒，用于调节口型幅度与过渡节奏。','AudioMouthControllerAdvanced connects AudioSource to SkinnedMeshRenderer, controlling mouth opening through talkBlendShapeIndex. During playback, it reads audio amplitude, applies a multiplier and smooths weight changes with SmoothDamp. A default multiplier of 100 and smoothing time of 0.1 seconds tune the movement range and transitions.')}${note('单一 talk BlendShape 随音量变化驱动嘴部开合，将声音的节奏转化为直观的角色反馈。','A single talk BlendShape follows audio amplitude, translating the rhythm of speech into visible character feedback.')}</div><div><h3>${t('身体与字幕提供额外反馈','Body and captions add feedback')}</h3>${para('身体在 idle 与讲话动画之间切换，配合声音呈现对话状态。TypewriterTextUI 使用 UGUI Text 逐字显示回答，并在固定区域内换行与自动滚动。默认每字 0.08 秒，可调范围为 0.03–0.2 秒，便于调整字幕的阅读节奏。','The body switches between idle and speaking animation to express the conversation state. TypewriterTextUI reveals the answer character by character using UGUI Text, with wrapping and automatic scrolling in a fixed area. Its default interval is 0.08 seconds per character, adjustable from 0.03 to 0.2 seconds to tune the reading pace.')}${note('TTS 将回答文字转换为语音，字幕保留可阅读的内容，身体动作与口型则让回答以人物的方式呈现。','TTS gives the answer a voice, captions keep its content readable, and body and mouth movement give it a character presence.')}</div></div>
  <div class="yz-grid">${photo('mouth','口型代码：音频振幅、BlendShape 与平滑','Lip code: audio amplitude, BlendShape and smoothing')}${photo('subtitles','字幕代码：逐字显示、换行与滚动','Caption code: timed text, wrapping and scrolling')}</div></section>
  <section class="yz-block" id="yz-06">${head('06','把多个服务接成一个展项','Integrating services into one exhibit','INTERFACES / STATE / EXPERIENCE')}
  <div class="yz-table-wrap"><table><thead><tr><th>${t('接口','Interface')}</th><th>${t('传递内容','Payload')}</th><th>${t('实现方式','Implementation')}</th></tr></thead><tbody>
  <tr><td>OnlineAudio → AudioRecorder</td><td>${t('音频字节队列','Queued audio bytes')}</td><td>16 kHz · ConcurrentQueue&lt;byte[]&gt;</td></tr>
  <tr><td>AudioRecorder ↔ FunASR</td><td>${t('音频 / 识别文本','Audio / recognized text')}</td><td>WebSocket · OnOpen / OnMessage / OnError</td></tr>
  <tr><td>Unity → Coze</td><td>${t('问题、角色上下文与用户标识','Question, persona context and user identity')}</td><td>Coze.cs · /v3/chat · local/cloud switch</td></tr>
  <tr><td>Coze → Ollama</td><td>${t('模型推理请求','Model inference request')}</td><td>${t('Ollama 本地推理 · Qwen2.5','Local inference through Ollama · Qwen2.5')}</td></tr>
  <tr><td>TTS → Unity</td><td>${t('回答声音','Spoken answer')}</td><td>${t('语音播放 → 口型驱动 → 动画切换','Audio playback → lip movement → animation switching')}</td></tr></tbody></table></div>
  <h3>${t('一次对话的状态视图','A conversation as a state sequence')}</h3><p class="yz-states">${t('待机 → 唤醒 → 聆听 → 生成回答 → 讲话 → 回到待机','IDLE → WAKE → LISTEN → GENERATE → SPEAK → IDLE')}</p>
  ${note('交互流程示意：从待机、聆听到讲话，不同阶段通过提示文字与人物状态向观众传递反馈，帮助观众理解何时提问、何时等待与何时聆听。','Interaction sequence: prompts and character states communicate the progression from idle to listening and speaking, helping visitors understand when to ask, wait and listen.')}
  <div class="yz-three"><div><h3>${t('现场声音','Gallery sound')}</h3>${para('后续优化将围绕展厅的真实声环境展开，重点关注背景噪声、唤醒灵敏度与麦克风拾音，让语音入口更适应多人参观的使用场景。','Further development will focus on the gallery’s acoustic environment, including background noise, wake sensitivity and microphone pickup, to adapt voice interaction to shared visitor settings.')}</div><div><h3>${t('等待与中断','Waiting and interruption')}</h3>${para('下一步希望细化等待提示、断连恢复与打断后的音频和字幕处理，使对话中的停顿和转场也成为清晰的体验反馈。','The next iteration will refine waiting prompts, reconnection and audio-caption handling after interruptions, making pauses and transitions a clearer part of the conversation.')}</div><div><h3>${t('性能与内容','Performance and content')}</h3>${para('本地模型推理与 HDRP 渲染共同构成现场运行的技术基础。后续将结合帧率、显存占用与语音响应时间优化资源分配，并持续完善人物知识与回答内容。','Local model inference and HDRP rendering form the technical foundation of the installation. Future refinement will consider frame rate, GPU memory and voice response time alongside continued development of the character’s knowledge and dialogue.')}</div></div></section>
  <section class="yz-block" id="yz-07">${head('07','让技术回到观众面前','Returning the technology to the visitor','ON-SITE ENCOUNTER')}
  ${para('竖向屏幕以全身尺度呈现晏子，与观众的站姿和视线形成面对面的关系。观众靠近、提问，人物通过姿态、声音与字幕回应，让典籍中的历史人物进入当代展厅，也让文化内容通过一次具体的对话被接近。','A portrait display presents Yan Zi at full-body scale, creating a face-to-face relationship with the visitor’s stance and gaze. Visitors approach and ask questions; posture, voice and captions shape the reply. The encounter brings a figure from classical texts into the contemporary gallery, offering a conversational entry into cultural content.')}
  <div class="yz-site-grid">${photo('site-01','对话中的人物姿态','Character posture during an encounter')}${photo('site-02','人物与字幕区域','Character and caption area')}${photo('site-03','角色动作的另一状态','Another character animation state')}${photo('site-04','屏幕与观众的尺度关系','Display and visitor scale')}${photo('site-05','展厅环境与交互站位','Gallery setting and interaction position')}</div></section>
  <footer class="yz-source">${t('项目过程与现场记录 / 角色制作、系统集成与展厅呈现。点击图片可查看完整分辨率。','Process and installation / Character development, system integration and the gallery encounter. Select an image to inspect it at full resolution.')}</footer>
  </article>`;
}
export function createYanziArticle(t,openAsset){
 const template=document.createElement('template');template.innerHTML=yzMarkup(t);
 const article=template.content.firstElementChild;
 article.querySelectorAll('[data-yz-asset]').forEach(button=>button.onclick=()=>openAsset(yanziAssets[button.dataset.yzAsset].full,button.querySelector('img').alt));
 article.querySelectorAll('[data-yz-jump]').forEach(button=>button.onclick=()=>article.querySelector('#'+button.dataset.yzJump).scrollIntoView({behavior:'instant',block:'start'}));
 return article;
}
